ValidationRule.errorConditionFormula:
AND (
    /* If owner is Changed */
    ISCHANGED(OwnerId),
    /* If the owner is a queue and not a user */
    LEFT(OwnerId,3) = '00G',
    OR(
        NOT (
            /* New Queue should be present in allowed queues for the country */
            CONTAINS (
                /* fetch allowed queues */
                VLOOKUP(
                    $ObjectType.CountryGroup__c.Fields.Queues_Allowed__c,
                    $ObjectType.CountryGroup__c.Fields.Name,
                    $User.Country
                ),
                Owner:Queue.Name
            )
        )
    )
)
